namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z0-9]{6,10}$", ErrorMessage = "Student ID must be 6-10 alphanumeric characters.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Pure and applied mathematics including analysis, algebra, and statistics." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Literature, writing, and linguistic studies." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Exploration of historical events, cultures, and civilizations." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, CourseCode = "CS 101", Title = "Introduction to Programming", Description = "Foundational course covering programming concepts using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and education. She holds a PhD from MIT and specializes in programming language design.", IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, CourseCode = "CS 201", Title = "Data Structures & Algorithms", Description = "In-depth study of data structures (trees, graphs, hash tables) and algorithm design techniques including divide-and-conquer, dynamic programming, and greedy algorithms.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park is a researcher in algorithm optimization with publications in top-tier conferences. He received his PhD from Stanford University.", IsFeatured = true },
            new() { Id = 3, DepartmentId = 1, CourseCode = "CS 350", Title = "Operating Systems", Description = "Study of operating system design including process management, memory management, file systems, and concurrency.", Credits = 4, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez has contributed to the Linux kernel and has extensive industry experience at major technology companies." },
            new() { Id = 4, DepartmentId = 2, CourseCode = "MATH 101", Title = "Calculus I", Description = "Introduction to differential calculus including limits, derivatives, and applications of differentiation.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator with a passion for making calculus accessible to all students.", IsFeatured = true },
            new() { Id = 5, DepartmentId = 2, CourseCode = "MATH 202", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Emily Watson", InstructorBio = "Dr. Watson specializes in applied linear algebra and numerical methods. She consults for aerospace engineering firms." },
            new() { Id = 6, DepartmentId = 2, CourseCode = "MATH 301", Title = "Probability & Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator with a passion for making calculus accessible to all students." },
            new() { Id = 7, DepartmentId = 3, CourseCode = "ENG 110", Title = "College Writing", Description = "Development of writing skills through essays, research papers, and critical analysis of texts.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Prof. David Miller", InstructorBio = "Prof. Miller is a published author and writing coach with over 20 years of teaching experience.", IsFeatured = true },
            new() { Id = 8, DepartmentId = 3, CourseCode = "ENG 250", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present, exploring major works and literary movements.", Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM", InstructorName = "Dr. Angela Torres", InstructorBio = "Dr. Torres is a specialist in 20th-century American fiction and has published two books on the subject." },
            new() { Id = 9, DepartmentId = 4, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes laboratory component with hands-on experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Thu 2:00–4:00 PM", InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster is an experimental physicist who previously worked at CERN on particle detection systems." },
            new() { Id = 10, DepartmentId = 4, CourseCode = "PHYS 220", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:15 PM", InstructorName = "Dr. Nina Patel", InstructorBio = "Dr. Patel's research focuses on electromagnetic theory and its applications in communications technology." },
            new() { Id = 11, DepartmentId = 5, CourseCode = "HIST 101", Title = "World History I", Description = "Survey of world civilizations from ancient times through the early modern period.", Credits = 3, Schedule = "Tue/Thu 2:30–3:45 PM", InstructorName = "Dr. Michael Brown", InstructorBio = "Dr. Brown is a historian specializing in comparative civilizations and has led archaeological expeditions in the Mediterranean." },
            new() { Id = 12, DepartmentId = 5, CourseCode = "HIST 205", Title = "Modern European History", Description = "European history from the Enlightenment through the 21st century, covering political, social, and cultural developments.", Credits = 3, Schedule = "Mon/Wed 10:00–11:15 AM", InstructorName = "Dr. Claire Dubois", InstructorBio = "Dr. Dubois holds a joint appointment with the Department of Political Science and specializes in modern French history.", IsFeatured = true }
        };
    }

    public List<Department> GetAllDepartments() => _departments;

    public Department? GetDepartmentById(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public Course? GetCourseById(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }
}

