@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService
@rendermode InteractiveServer

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p>Submit your enrollment request below. You will receive confirmation via your university email.</p>

@if (_submitted)
{
    <div class="alert alert-success" role="alert">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@_model.StudentName</strong>. Your enrollment request for
            <strong>@_courses.First(c => c.Id == _model.CourseId).Title</strong> has been received.</p>
        <hr>
        <p class="mb-0">You will receive a confirmation email at your university address.</p>
    </div>
    <button class="btn btn-primary" @onclick="Reset">Submit Another Request</button>
}
else
{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="enrollment">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="studentName" class="form-label">Full Name</label>
            <InputText id="studentName" class="form-control" @bind-Value="_model.StudentName" />
            <ValidationMessage For="() => _model.StudentName" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <InputText id="studentId" class="form-control" @bind-Value="_model.StudentId" placeholder="e.g. STU12345" />
            <ValidationMessage For="() => _model.StudentId" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <InputSelect id="courseId" class="form-select" @bind-Value="_model.CourseId">
                <option value="0">-- Select a course --</option>
                @foreach (var course in _courses)
                {
                    <option value="@course.Id">@course.CourseCode - @course.Title</option>
                }
            </InputSelect>
            <ValidationMessage For="() => _model.CourseId" class="text-danger" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
    </EditForm>
}

@code {
    private EnrollmentRequest _model = new();
    private List<Course> _courses = new();
    private bool _submitted;

    protected override void OnInitialized()
    {
        _courses = CatalogService.GetAllCourses();
    }

    private void HandleSubmit()
    {
        _submitted = true;
    }

    private void Reset()
    {
        _model = new EnrollmentRequest();
        _submitted = false;
    }
}
